#!/bin/bash
# Openbox Test Runner Script
# Run this script to execute all tests locally

set -e

SCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"
PROJECT_ROOT=\"$(dirname \"$SCRIPT_DIR\")\"

# Colors for output
RED='\\033[0;31m'
GREEN='\\033[0;32m'
YELLOW='\\033[1;33m'
NC='\\033[0m' # No Color

# Function to print colored output
print_status() {
    echo -e \"${GREEN}[INFO]${NC} $1\"
}

print_warning() {
    echo -e \"${YELLOW}[WARN]${NC} $1\"
}

print_error() {
    echo -e \"${RED}[ERROR]${NC} $1\"
}

# Check dependencies
check_dependencies() {
    print_status \"Checking dependencies...\"\n    \n    # Check for meson\n    if ! command -v meson &> /dev/null; then\n        print_error \"meson not found. Please install meson.\"\n        exit 1\n    fi\n    \n    # Check for ninja\n    if ! command -v ninja &> /dev/null; then\n        print_error \"ninja not found. Please install ninja-build.\"\n        exit 1\n    fi\n    \n    # Check for Xvfb\n    if ! command -v Xvfb &> /dev/null; then\n        print_warning \"Xvfb not found. Some tests will be skipped.\"\n    fi\n    \n    # Check for pytest\n    if ! command -v pytest &> /dev/null; then\n        print_warning \"pytest not found. Python tests will be skipped.\"\n    fi\n    \n    # Check for cargo\n    if ! command -v cargo &> /dev/null; then\n        print_warning \"cargo not found. Rust tests will be skipped.\"\n    fi\n}\n\n# Build the project\nbuild_project() {
n    print_status \"Building project...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    # Build C/C++ components\n    if [ ! -d \"build\" ]; then\n        meson setup build --buildtype=debug\n    fi\n    \n    ninja -C build\n    \n    # Build Rust components\n    if command -v cargo &> /dev/null; then\n        cargo build --workspace\n    fi\n    \n    print_status \"Build complete\"\n}\n\n# Run C/C++ unit tests\nrun_c_tests() {\n    print_status \"Running C/C++ unit tests...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    if [ -d \"build\" ]; then\n        meson test -C build --print-errorlogs || {\n            print_error \"C/C++ tests failed\"\n            return 1\n        }\n    else\n        print_warning \"Build directory not found, skipping C tests\"\n    fi\n}\n\n# Run Python integration tests\nrun_python_tests() {\n    print_status \"Running Python integration tests...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    if command -v pytest &> /dev/null; then\n        # Check if Xvfb is available\n        if command -v Xvfb &> /dev/null; then\n            pytest tests/python/ -v --xvfb --tb=short || {\n                print_error \"Python tests failed\"\n                return 1\n            }\n        else\n            print_warning \"Xvfb not available, running tests without X11\"\n            pytest tests/python/ -v --tb=short -m \"not x11\" || {\n                print_error \"Python tests failed\"\n                return 1\n            }\n        fi\n    else\n        print_warning \"pytest not found, skipping Python tests\"\n    fi\n}\n\n# Run Rust tests\nrun_rust_tests() {\n    print_status \"Running Rust tests...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    if command -v cargo &> /dev/null; then\n        cargo test --workspace -- --nocapture || {\n            print_error \"Rust tests failed\"\n            return 1\n        }\n    else\n        print_warning \"cargo not found, skipping Rust tests\"\n    fi\n}\n\n# Run static analysis\nrun_static_analysis() {\n    print_status \"Running static analysis...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    # Run cppcheck\n    if command -v cppcheck &> /dev/null; then\n        print_status \"Running cppcheck...\"\n        cppcheck --enable=all --error-exitcode=1 \\\n            --suppress=missingIncludeSystem \\\n            -I. openbox/ obt/ obrender/ 2>&1 | head -50 || {\n            print_warning \"cppcheck found issues (non-fatal)\"\n        }\n    fi\n    \n    # Run clang-tidy\n    if command -v clang-tidy &> /dev/null; then\n        print_status \"Running clang-tidy...\"\n        find openbox obt obrender -name \"*.c\" -not -path \"*/tests/*\" | \\\n        head -20 | xargs clang-tidy || {\n            print_warning \"clang-tidy found issues (non-fatal)\"\n        }\n    fi\n    \n    # Run clippy\n    if command -v cargo &> /dev/null; then\n        print_status \"Running clippy...\"\n        cargo clippy --workspace -- -D warnings || {\n            print_warning \"clippy found issues (non-fatal)\"\n        }\n    fi\n}\n\n# Run memory safety tests\nrun_memory_tests() {\n    print_status \"Running memory safety tests...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    # Valgrind tests\n    if command -v valgrind &> /dev/null && [ -f \"./build/openbox/openbox\" ]; then\n        print_status \"Running Valgrind checks...\"\n        valgrind --leak-check=full --error-exitcode=1 \\\n            ./build/openbox/openbox --version 2>&1 | tail -20 || {\n            print_error \"Valgrind found memory issues\"\n            return 1\n        }\n    else\n        print_warning \"Valgrind not available, skipping memory tests\"\n    fi\n}\n\n# Generate coverage report\ngenerate_coverage() {\n    print_status \"Generating coverage report...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    # C coverage\n    if [ -d \"build\" ] && command -v gcovr &> /dev/null; then\n        ninja -C build coverage 2>/dev/null || true\n        gcovr -r . --html --html-details -o coverage.html 2>/dev/null || {\n            print_warning \"Failed to generate C coverage\"\n        }\n    fi\n    \n    # Python coverage\n    if command -v pytest &> /dev/null; then\n        pytest tests/python/ --cov=openbox_dbus --cov-report=html \\\n            --cov-report=xml 2>/dev/null || {\n            print_warning \"Failed to generate Python coverage\"\n        }\n    fi\n    \n    # Rust coverage\n    if command -v cargo &> /dev/null && command -v cargo-tarpaulin &> /dev/null; then\n        cargo tarpaulin --out Html --out Xml 2>/dev/null || {\n            print_warning \"Failed to generate Rust coverage\"\n        }\n    fi\n    \n    print_status \"Coverage reports generated\"\n}\n\n# Run all tests\nrun_all_tests() {\n    print_status \"Running all tests...\"\n    \n    check_dependencies\n    build_project\n    run_c_tests\n    run_python_tests\n    run_rust_tests\n    run_static_analysis\n    run_memory_tests\n    generate_coverage\n    \n    print_status \"All tests complete!\"\n}\n\n# Usage information\nusage() {\n    echo \"Openbox Test Runner\"\n    echo \"\"\n    echo \"Usage: $0 [COMMAND]\"\n    echo \"\"\n    echo \"Commands:\"\n    echo \"  all          Run all tests (default)\"\n    echo \"  build        Build the project\"\n    echo \"  c            Run C/C++ unit tests\"\n    echo \"  python       Run Python integration tests\"\n    echo \"  rust         Run Rust tests\"\n    echo \"  static       Run static analysis\"\n    echo \"  memory       Run memory safety tests\"\n    echo \"  coverage     Generate coverage reports\"\n    echo \"  clean        Clean build artifacts\"\n    echo \"  help         Show this help message\"\n    echo \"\"\n    echo \"Examples:\"\n    echo \"  $0                    # Run all tests\"\n    echo \"  $0 python             # Run only Python tests\"\n    echo \"  $0 coverage           # Generate coverage reports\"\n}\n\n# Clean build artifacts\nclean() {\n    print_status \"Cleaning build artifacts...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    rm -rf build build-asan\n    cargo clean 2>/dev/null || true\n    rm -rf htmlcov coverage.xml cobertura.xml\n    rm -f coverage.html\n    \n    print_status \"Clean complete\"\n}\n\n# Main\nmain() {\n    case \"${1:-all}\" in\n        all)\n            run_all_tests\n            ;;\n        build)\n            build_project\n            ;;\n        c)\n            run_c_tests\n            ;;\n        python)\n            run_python_tests\n            ;;\n        rust)\n            run_rust_tests\n            ;;\n        static)\n            run_static_analysis\n            ;;\n        memory)\n            run_memory_tests\n            ;;\n        coverage)\n            generate_coverage\n            ;;\n        clean)\n            clean\n            ;;\n        help|--help|-h)\n            usage\n            ;;\n        *)\n            print_error \"Unknown command: $1\"\n            usage\n            exit 1\n            ;;\n    esac\n}\n\nmain \"$@\"\n